PART = dict(id="part1", el="Σεπτέμβριος – Οκτώβριος", en="September – October",
            intro_el="Τα σχολεία ανοίγουν, η μπάλα ξεκινά, και η πολυκατοικία της οδού Αιγίνης 14 ξυπνάει από το καλοκαίρι: η ομάδα μπάσκετ του Νίκου, τα πρώτα γκολ του Άρη, ένα κουτσομπολιό σε εφημερίδα, ένα ματς τένις και ένα ασανσέρ που κολλάει.",
            intro_en="Schools open, the football season kicks off, and the block at 14 Aiginis Street wakes up from summer: Nikos's basketball team, Aris's first goals, a piece of tabloid gossip, a game of tennis and a lift that gets stuck.")

